{
  "strategy_id": "agent_practical",
  "strategy_title": "비용 우선: 2주 차 RAG 시제품 구축 로드맵",
  "summary": "사용자의 2주(총 6시간) 가용 시간과 20,000원 예산을 고려하여, 무료 Microsoft Learn 자료를 활용한 최소 RAG 시제품 구축 계획을 수립했습니다. Python 기초는 제외하고, LLM/RAG 개념 이해와 실제 코드 구현에 집중합니다. 검색 성공, 근거 누락, 답변 불가 3가지 케이스를 구분하는 로직을 포함하며, 유료 서비스나 추가 비용 발생 없이 진행됩니다.",
  "project_goal": "가상 규정 3건에서 질문 5건의 근거를 표시하고, 근거 없는 질문은 구분하는 최소 RAG 시제품 구현",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "RAG 아키텍처 이해 및 환경 설정",
      "duration": "1.5 hours",
      "focus": "RAG의 기본 흐름(문서 분할, 임베딩, 검색, 생성) 이해 및 Python 환경에서 필요한 라이브러리(FAISS, LangChain 등) 설치"
    },
    {
      "step": 2,
      "title": "벡터 데이터베이스 구축 및 문서 처리",
      "duration": "1.5 hours",
      "focus": "가상 규정 3건을 텍스트로 변환하고, 임베딩 모델을 사용하여 벡터 데이터베이스에 저장하는 코드 작성"
    },
    {
      "step": 3,
      "title": "검색 로직 구현 및 케이스 구분",
      "duration": "1.5 hours",
      "focus": "질문 5건에 대한 유사도 검색 구현 및 '검색 성공', '근거 누락(유사도 낮음)', '답변 불가(관련 문서 없음)' 로직 분기 처리"
    },
    {
      "step": 4,
      "title": "LLM 연동 및 최종 시제품 검증",
      "duration": "1.5 hours",
      "focus": "검색된 근거를 프롬프트에 주입하여 LLM 응답 생성 및 5개 질문의 출력 결과 검증(근거 표시 여부 확인)"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기초 이해 및 환경 준비",
      "duration": "1.5 hours",
      "focus_goal": "RAG 개념 정립 및 개발 환경 구축",
      "key_actions": [
        "Microsoft Learn 'Microsoft Foundry를 사용하여 생성 AI 모델 성능 최적화' 모듈 중 RAG 관련 섹션 학습",
        "Python 가상환경 생성 및 RAG 구현에 필요한 패키지 설치"
      ],
      "deliverables": [
        "RAG 아키텍처 다이어그램(개념적)",
        "설치 완료된 Python 개발 환경"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "데이터 처리 및 벡터화",
      "duration": "1.5 hours",
      "focus_goal": "가상 규정 데이터를 벡터 데이터베이스에 저장",
      "key_actions": [
        "가상 규정 3건 텍스트 파일 준비",
        "문서 분할(Chunking) 및 임베딩 코드 작성",
        "벡터 데이터베이스(예: FAISS)에 데이터 저장"
      ],
      "deliverables": [
        "벡터화 완료된 가상 규정 데이터셋",
        "데이터 전처리 및 저장 스크립트"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 3,
      "phase_name": "검색 및 로직 구현",
      "duration": "1.5 hours",
      "focus_goal": "질문별 검색 결과 분류 로직 구현",
      "key_actions": [
        "질문 5건에 대한 유사도 검색 함수 구현",
        "유사도 임계값을 설정하여 '검색 성공', '근거 누락', '답변 불가' 케이스 구분",
        "각 케이스에 따른 응답 메시지 템플릿 정의"
      ],
      "deliverables": [
        "케이스 구분 로직이 포함된 검색 모듈",
        "테스트 질문 5건에 대한 검색 결과 로그"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 4,
      "phase_name": "LLM 연동 및 최종 검증",
      "duration": "1.5 hours",
      "focus_goal": "최종 RAG 시제품 완성 및 결과 확인",
      "key_actions": [
        "검색된 근거를 컨텍스트로 사용하여 LLM 프롬프트 구성",
        "LLM API 호출 및 응답 생성",
        "5개 질문에 대한 최종 출력 확인(근거 표시, 구분 여부)"
      ],
      "deliverables": [
        "최종 RAG 시제품 코드",
        "5개 질문의 실행 결과 보고서(근거 포함 여부 확인)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_d1f2eed6c592"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": []
}

{
  "strategy_id": "agent_practical",
  "strategy_title": "2주 집중: 가상 규정 기반 최소 RAG 시제품 구축",
  "summary": "Python 기반 개발 경험을 활용하여, 2주(주 3시간) 동안 '가상 규정 3건'을 데이터로 활용한 최소 RAG 시제품을 구축하는 로드맵입니다. LLM/RAG 초보자를 위해 벡터 DB 설정, 임베딩, 검색 로직, 그리고 '근거 표시' 및 '답변 불가' 판별 로직 구현에 집중합니다. 유료 서비스 없이 무료 오픈소스 도구와 Microsoft Learn 무료 모듈을 활용하여 예산(20,000원)과 시간 제약 내에서 목표를 달성합니다.",
  "project_goal": "가상 규정 3건에서 질문 5건의 근거를 표시하고, 근거 없는 질문은 구분하는 최소 RAG 시제품 구현",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "환경 구축 및 데이터 전처리",
      "duration": "3.5 hours",
      "focus": "Python 환경 설정, 가상 규정 데이터 구조화, 임베딩 모델 선택 및 테스트"
    },
    {
      "step": 2,
      "title": "벡터 저장소 구축 및 검색 로직 구현",
      "duration": "3.5 hours",
      "focus": "ChromaDB 등 경량 벡터 DB 설정, 문서 분할(Chunking), 유사도 검색 API 구현"
    },
    {
      "step": 3,
      "title": "RAG 파이프라인 및 응답 생성 로직",
      "duration": "3.5 hours",
      "focus": "검색 결과 기반 프롬프트 구성, LLM 호출, 출처(근거) 포함 응답 포맷 설계"
    },
    {
      "step": 4,
      "title": "경계 사례 처리 및 시제품 검증",
      "duration": "3.5 hours",
      "focus": "근거 없는 질문 판별 로직(임계값 설정), 5개 질문 테스트, 결과 분석 및 개선"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기반 구축 및 데이터 준비",
      "duration": "1.5 weeks",
      "focus_goal": "가상 규정 데이터를 벡터화하여 검색 가능한 상태로 만드는 것",
      "key_actions": [
        "Python 가상환경 생성 및 langchain, chromadb, openai(또는 무료 대안) 라이브러리 설치",
        "가상 규정 3건을 텍스트 파일로 정리하고, 의미 단위로 분할(Chunking)하는 스크립트 작성",
        "무료 임베딩 모델(예: sentence-transformers)을 활용하여 문서 벡터 생성 및 ChromaDB에 저장",
        "검색 정확도를 확인하기 위해 간단한 유사도 검색 테스트 수행"
      ],
      "deliverables": [
        "가상 규정 데이터셋(3건) 및 전처리 스크립트",
        "벡터 데이터베이스 초기화 및 데이터 로드 완료 코드"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "RAG 로직 구현 및 검증",
      "duration": "0.5 weeks",
      "focus_goal": "검색된 근거를 바탕으로 답변을 생성하고, 근거가 없는 경우를 구분하는 로직 완성",
      "key_actions": [
        "검색된 상위 N개 문서를 컨텍스트로 사용하여 LLM 프롬프트 템플릿 설계",
        "응답에 '근거 출처'를 명시하도록 출력 포맷을 정의",
        "검색 점수(Similarity Score)가 임계값 이하일 경우 '답변 불가'로 판별하는 로직 구현",
        "준비된 5개 질문(근거 있음 3건, 근거 없음 2건)으로 시제품 실행 및 결과 검증"
      ],
      "deliverables": [
        "최소 RAG 시제품 실행 스크립트",
        "5개 질문 테스트 결과 리포트(근거 표시 여부, 답변 불가 판별 여부 확인)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": [],
  "clarification_questions": []
}

